      return {txt:trial?'Prova terminata':'Scaduto',right:'dal '+pfDate(endIso),cls:'exp',pct:100,note:(!trial&&over<grace)?('Ancora '+(grace-over)+(grace-over===1?' giorno':' giorni')+' di tolleranza'):'Rinnova per continuare a usare il piano'};
