  function stBillingGet(force){
    if(!force&&window.liaBilling&&Date.now()-(window.liaBillingAt||0)<20000)return Promise.resolve(window.liaBilling);
    return fetch('/api/billing?t='+encodeURIComponent(token),{cache:'no-store'}).then(function(r){return r.json().then(function(d){if(!r.ok)throw new Error(d&&d.error||'');return d})}).then(function(d){window.liaBilling=d;window.liaBillingAt=Date.now();return d}).catch(function(){return window.liaBilling||null});
  }
  function stLoadBilling(){stBillingGet(false).then(function(){stRenderPay()})}
  function stRenderPay(){
    var B=window.liaBilling,card=stEl('subPay'),btn=stEl('subPayBtn'),cc=stEl('subCancelCard');if(!card)return;
    if(!B||!B.configured||!B.status){card.hidden=true;return}
    var D=stD(),price=stEur(B.price_eur!=null?B.price_eur:25)+' al mese',now=Date.now(),DAY=86400000;
    var title='',tx='',label='',mode='checkout';
    var endIso=B.status==='trial'?B.trial_ends_at:B.period_end,endTxt=endIso?pfDate(endIso):'';
    var expired=endIso&&new Date(endIso).getTime()<now;
    var graceDays=(D.sub&&D.sub.grace_days)||3,leftDays=expired?Math.max(0,Math.ceil((new Date(endIso).getTime()+graceDays*DAY-now)/DAY)):0;
    if(B.status==='cancelled'){title='Riattiva l’abbonamento';tx='Riparti quando vuoi: ritrovi clienti e appuntamenti come li hai lasciati. '+price+'.';label='Riattiva · '+price}
    else if(B.has_stripe){mode='portal';label='Gestisci pagamento e fatture';
      if(B.status==='trial'){title='Abbonamento attivato';tx='Non paghi nulla fino al '+endTxt+': il primo addebito ('+price+') parte quel giorno. Puoi disdire quando vuoi.'}
      else if(B.cancel_at_period_end){title='Disdetta registrata';tx='Il piano resta attivo fino al '+endTxt+', poi non si rinnova. Puoi cambiare idea dal pulsante qui sotto.'}
      else{title='Abbonamento attivo';tx='Si rinnova il '+endTxt+' ('+price+'). Da qui aggiorni la carta, scarichi le ricevute o disdici: il piano resta attivo fino alla fine del periodo già pagato.'}}
    else if(B.status==='trial'){title='Attiva il tuo abbonamento';tx='Prova gratuita fino al '+endTxt+'. Se lo attivi adesso non paghi nulla fino a quel giorno: poi '+price+', disdici quando vuoi.';label='Attiva l’abbonamento · '+price}
    else if(expired){title='Abbonamento scaduto';tx=(leftDays>0?'Hai ancora '+leftDays+(leftDays===1?' giorno':' giorni')+' di tolleranza, poi la pagina di prenotazione si ferma. ':'La pagina di prenotazione è ferma. ')+'Rinnova per ripartire subito: '+price+'.';label='Rinnova · '+price}
    else{title='Attiva il rinnovo automatico';tx='Il piano è attivo'+(endTxt?' fino al '+endTxt:'')+'. Attiva il rinnovo automatico per non fermarti: '+price+', disdici quando vuoi.';label='Attiva il rinnovo · '+price}
    stText('subPayTitle',title);stText('subPayTx',tx);btn.textContent=label;btn.setAttribute('data-mode',mode);btn.disabled=false;card.hidden=false;
    if(cc)cc.hidden=!!B.has_stripe&&B.status!=='cancelled'; /* con Stripe la disdetta si fa dal portale */
  }
  function stPay(){
    var btn=stEl('subPayBtn');if(!btn||btn.disabled)return;
    var mode=btn.getAttribute('data-mode')||'checkout',old=btn.textContent;btn.disabled=true;btn.textContent='Apro il pagamento…';stMsg('subPayMsg','');
    fetch('/api/billing?t='+encodeURIComponent(token),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:mode})})
      .then(function(r){return r.json().catch(function(){return {}}).then(function(d){return {ok:r.ok,d:d}})})
      .then(function(x){
        if(x.ok&&x.d.url){window.location.href=x.d.url;return}
        if(x.d&&x.d.can_manage){stBillingGet(true).then(stRenderPay)}
        btn.disabled=false;btn.textContent=old;stMsg('subPayMsg',(x.d&&x.d.error)||'Non sono riuscito ad aprire il pagamento. Riprova tra poco.',true);
      }).catch(function(){btn.disabled=false;btn.textContent=old;stMsg('subPayMsg','Connessione assente. Riprova.',true)});
  }
